arguments.command:
cd /tmp/symbols

# Symbolicate mono frames using the debug file
# Frames: #01=0x222098, #02=0x222234, #03=0x19bac0, #06=0x19bc14
echo "=== libmonosgen-2.0.so frames ==="
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  result=$(addr2line -C -f -e libmonosgen-2.0.so.dbg "$addr" 2>&1)
  echo "  pc $addr -> $result"
done

# Also try using dynamic symbol table for a quick lookup
echo ""
echo "=== Dynamic symbol nearest matches ==="
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  # Find nearest dynamic symbol
  readelf --dyn-syms libmonosgen-2.0.so 2>/dev/null | awk -v target="$addr" '
    BEGIN { target_dec = strtonum(target); best_name=""; best_addr=0; best_diff=999999999 }
    /FUNC/ {
      sym_addr = strtonum("0x" $2);
      sym_size = strtonum($3);
      if (sym_addr <= target_dec && target_dec < sym_addr + sym_size) {
        diff = target_dec - sym_addr;
        if (diff < best_diff) { best_diff = diff; best_name = $8; best_addr = sym_addr }
      }
    }
    END { if (best_name != "") printf "  pc %s -> %s+0x%x\n", target, best_name, best_diff; else printf "  pc %s -> (no match)\n", target }
  '
done

